import React from 'https://cdn.jsdelivr.net/npm/react@18.2.0/+esm'
import reactDom from 'https://cdn.jsdelivr.net/npm/react-dom@18.2.0/+esm'
import { Card, Spin } from 'https://cdn.jsdelivr.net/npm/antd@5.11.1/+esm'

function TableauDashboard() {
  const [url, setUrl] = React.useState('');
  const [error, setError] = React.useState(null);
  const [loading, setLoading] = React.useState(true);

  React.useEffect(() => {
    const loadTableau = async () => {
      try {
        setLoading(true);
        // Wait for TableauAuth to be available in store
        if (!appsmith.store.TableauAuth) {
          throw new Error('TableauAuth not found in store. Please ensure it is initialized.');
        }

        const result = await appsmith.store.TableauAuth.generateTableauUrl();
        console.log('Generated URL:', result);
        setUrl(result);
        setError(null);
      } catch (err) {
        console.error('Error loading Tableau:', err);
        setError(err.message);
      } finally {
        setLoading(false);
      }
    };

    // Add Tableau Embedding API script
    const script = document.createElement('script');
    script.type = 'module';
    script.src = 'https://public.tableau.com/javascripts/api/tableau.embedding.3.latest.min.js';
    document.head.appendChild(script);

    script.onload = loadTableau;

    return () => {
      // Cleanup blob URL on unmount
      if (url && url.startsWith('blob:')) {
        URL.revokeObjectURL(url);
      }
    };
  }, []);

  if (loading) {
    return (
      <Card style={{ width: '100%', height: '100%', display: 'flex', justifyContent: 'center', alignItems: 'center' }}>
        <Spin size="large" />
      </Card>
    );
  }

  if (error) {
    return (
      <Card style={{ width: '100%', height: '100%', padding: '20px' }}>
        <div style={{ color: 'red' }}>
          Error loading dashboard: {error}
          <br />
          <small>Try refreshing the page if this persists.</small>
        </div>
      </Card>
    );
  }

  return (
    <div style={{ width: '100%', height: '100%' }}>
      {url ? (
        <iframe
          src={url}
          style={{
            width: '100%',
            height: '100%',
            border: 'none',
            minHeight: '800px'
          }}
          allowFullScreen={true}
        />
      ) : (
        <Card>Loading dashboard...</Card>
      )}
    </div>
  );
}

function App() {
  return (
    <div style={{ width: '100%', height: '100%' }}>
      <TableauDashboard />
    </div>
  );
}

appsmith.onReady(() => {
  reactDom.render(<App />, document.getElementById("root"));
});
